//! Types for privacy residue, cache inspection, and purge operations.

use serde::{Deserialize, Serialize};

/// High-level category of disposable or rebuildable residue.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ResidueCategory {
    /// Temporary files generated by the operating system or applications.
    TemporaryFiles,
    /// Crash dumps and memory dumps from failed processes.
    CrashDumps,
    /// Visual thumbnail cache databases.
    ThumbnailCache,
    /// Precompiled graphics and compute shaders.
    ShaderCache,
    /// Web browser HTTP caches and bytecode caches.
    BrowserCache,
    /// Desktop application media, web, and session caches.
    AppCache,
    /// AI agent temporary files, scratchpads, and execution logs.
    AgentResidue,
    /// Recent document history, shortcuts, and taskbar Jump Lists.
    RecentActivity,
    /// Downloaded package archives from developer package managers.
    PackageCache,
}

impl ResidueCategory {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::TemporaryFiles => "temporary files",
            Self::CrashDumps => "crash dumps",
            Self::ThumbnailCache => "thumbnail cache",
            Self::ShaderCache => "shader cache",
            Self::BrowserCache => "browser cache",
            Self::AppCache => "app cache",
            Self::AgentResidue => "agent residue",
            Self::RecentActivity => "recent activity",
            Self::PackageCache => "package cache",
        }
    }

    pub fn group_title(self) -> &'static str {
        match self {
            Self::TemporaryFiles | Self::CrashDumps | Self::ThumbnailCache | Self::ShaderCache => {
                "System Residue"
            }
            Self::BrowserCache => "Browser Caches",
            Self::AgentResidue => "AI Agent Residue",
            Self::RecentActivity => "Recent Activity & Jump Lists",
            Self::PackageCache => "Developer Caches",
            Self::AppCache => "Application Caches",
        }
    }

    pub fn group_rank(self) -> u8 {
        match self {
            Self::TemporaryFiles | Self::CrashDumps | Self::ThumbnailCache | Self::ShaderCache => 1,
            Self::BrowserCache => 2,
            Self::AgentResidue => 3,
            Self::RecentActivity => 4,
            Self::PackageCache => 5,
            Self::AppCache => 6,
        }
    }
}

/// The mode governing default target selection.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum PurgeMode {
    /// Thorough clearing of supported privacy residue, including ordinary history.
    #[default]
    Aggressive,
    /// Retains caches whose rebuilding would disrupt convenience or workflows.
    Polite,
}

impl PurgeMode {
    pub fn display_name(self) -> &'static str {
        match self {
            Self::Aggressive => "thorough",
            Self::Polite => "polite",
        }
    }

    pub fn as_str(self) -> &'static str {
        match self {
            Self::Aggressive => "aggressive",
            Self::Polite => "polite",
        }
    }
}

/// Static specification for a reviewed residue target.
#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct ResidueSpec {
    pub id: String,
    pub title: String,
    pub category: ResidueCategory,
    pub description: String,
    pub trade_off: String,
    /// Whether this target is retained when running in polite mode.
    pub polite_retained: bool,
    /// Whether this target requires an explicit `--accept-risk <id>` flag.
    pub requires_risk_ack: bool,
}

/// An inspected item preview prior to any deletion.
#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct ResiduePreviewItem {
    pub id: String,
    pub title: String,
    pub category: ResidueCategory,
    /// Consequence of clearing this target, available before confirmation.
    #[serde(default)]
    pub trade_off: String,
    pub path_display: String,
    pub file_count: usize,
    pub size_bytes: u64,
    pub selected: bool,
    pub retained_reason: Option<String>,
    pub requires_risk_ack: bool,
}

/// The result of executing a purge operation on a single target.
#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct ResiduePurgeItem {
    pub id: String,
    pub title: String,
    pub category: ResidueCategory,
    /// Consequence of clearing this target, available before confirmation.
    #[serde(default)]
    pub trade_off: String,
    pub files_removed: usize,
    pub bytes_reclaimed: u64,
    pub files_retained: usize,
    pub error: Option<String>,
}

/// Free space TRIM / Deallocate status for a volume.
#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct TrimStatus {
    pub volume: String,
    pub media_type: String,
    pub supported: bool,
    pub executed: bool,
    pub message: String,
}

/// Versioned report for a purge preview or execution.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct PurgeReport {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub status: Option<CleanupStatus>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub transaction_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub journal_error: Option<String>,
    pub schema: u8,
    pub mode: PurgeMode,
    pub dry_run: bool,
    pub total_files_affected: usize,
    pub total_bytes_affected: u64,
    pub items: Vec<ResiduePurgeItem>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub trim: Option<TrimStatus>,
}

/// Durable cleanup progress. Running is unfinished, never proof of completion.
#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CleanupStatus {
    Pending,
    Running,
    Completed,
    Interrupted,
    Failed,
}

impl CleanupStatus {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Pending => "pending",
            Self::Running => "unfinished (completion unverified)",
            Self::Completed => "completed",
            Self::Interrupted => "interrupted",
            Self::Failed => "failed",
        }
    }
}

/// Aggregate metadata only. Never record deleted paths or file contents.
#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct CleanupTarget {
    pub id: String,
    pub status: CleanupStatus,
    pub files_removed: usize,
    pub bytes_removed: u64,
    pub files_retained: usize,
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct CleanupJournal {
    pub status: CleanupStatus,
    pub targets: Vec<CleanupTarget>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub trim: Option<CleanupStatus>,
}
